import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
HEADERS = {"Authorization": f"Bearer {os.getenv('API_TOKEN', '')}"}
session = requests.Session()
session.headers.update(HEADERS)


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    return response.json() if response.content else None


alerts = request("GET", "/alerts") or []
if isinstance(alerts, dict):
    alerts = alerts.get("alerts", [])

for alert in alerts:
    patient_id = alert.get("patient_id") or alert.get("patientId")
    if not patient_id:
        continue

    patient = request("GET", f"/patients/{patient_id}") or {}
    policy_details = alert.get("policy") or patient.get("policy") or {}
    policy_id = alert.get("policy_id") or patient.get("policy_id") or policy_details.get("policy_id")

    if policy_id:
        coverage = request("GET", f"/policies/{policy_id}/coverage")
        validation_payload = {
            "patient_id": patient_id,
            "policy_id": policy_id,
            "coverage": coverage,
            "patient": patient,
        }
    else:
        validation_payload = {
            "patient_id": patient_id,
            "policy": policy_details,
            "patient": patient,
        }

    eligibility = request("POST", "/policies/validate", json=validation_payload)
    readings = request("GET", f"/readings/{patient_id}") or []
    records = request("GET", f"/patients/{patient_id}/records") or {}
    medical_history = request("GET", f"/patients/{patient_id}/history") or {}

    findings = {
        "alert": alert,
        "insurance_eligibility": eligibility,
        "readings": readings,
        "records": records,
        "medical_history_reviewed": medical_history,
    }

    request(
        "POST",
        f"/records/{patient_id}",
        json={
            "type": "medical_history_finding",
            "findings": findings,
        },
    )

    claim_id = alert.get("claim_id") or patient.get("claim_id")
    if claim_id:
        request(
            "PUT",
            f"/claims/{claim_id}",
            json={
                "patient_id": patient_id,
                "medical_findings": findings,
                "insurance_eligibility": eligibility,
            },
        )

    alert_id = alert.get("id") or alert.get("alert_id")
    if alert_id:
        request("POST", "/alerts/dismiss", json={"alert_ids": [alert_id]})

settings = request("GET", "/settings")
compliance_status = request("GET", "/compliance/status")
print({"settings": settings, "compliance_status": compliance_status})

