import os
import requests

BASE_URL = os.environ.get("SOCBENCH_API_URL", "https://api.socbench.example").rstrip("/")
TOKEN = os.environ.get("SOCBENCH_API_TOKEN")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if TOKEN:
    session.headers["Authorization"] = f"Bearer {TOKEN}"


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None


# Trigger the hook to enable automatic threat alerts.
hook_result = request("POST", "/trigger-hook", json={
    "action": "enable_automatic_cybersecurity_threat_alerts"
})

# Retrieve threats and inventory software to identify associated vulnerabilities.
threats_result = request("GET", "/threats")
software_result = request("GET", "/software")
alerts_result = request("GET", "/alerts")

threats = threats_result if isinstance(threats_result, list) else threats_result.get("threats", [])
software = software_result if isinstance(software_result, list) else software_result.get("software", [])
alerts = alerts_result if isinstance(alerts_result, list) else alerts_result.get("alerts", [])

software_by_id = {
    str(item.get("id")): item
    for item in software
    if item.get("id") is not None
}
software_by_name = {
    str(item.get("name", "")).casefold(): item
    for item in software
    if item.get("name")
}

associated_vulnerabilities = []
for threat in threats:
    software_id = threat.get("software_id")
    software_name = threat.get("software_name")
    match = software_by_id.get(str(software_id)) if software_id is not None else None
    if match is None and software_name:
        match = software_by_name.get(str(software_name).casefold())

    if match:
        associated_vulnerabilities.append({
            "threat_id": threat.get("id"),
            "software_id": match.get("id"),
            "software_name": match.get("name"),
            "vulnerabilities": match.get("vulnerabilities", match.get("vulnerability_ids", [])),
        })

# Update existing alert rules for threat conditions; remove rules explicitly marked unnecessary.
for alert in alerts:
    alert_id = alert.get("id")
    if alert_id is None:
        continue

    if alert.get("unnecessary") is True or alert.get("status") == "obsolete":
        request("DELETE", f"/alerts/{alert_id}")
        continue

    conditions = alert.get("conditions", {})
    if isinstance(conditions, dict):
        conditions = dict(conditions)
        conditions["cybersecurity_threats"] = [
            {
                "threat_id": threat.get("id"),
                "type": threat.get("type"),
                "severity": threat.get("severity"),
            }
            for threat in threats
        ]
        conditions["associated_software_vulnerabilities"] = associated_vulnerabilities

    request("PUT", f"/alerts/{alert_id}", json={
        **alert,
        "conditions": conditions,
        "enabled": True,
    })

# Generate compliance reports for the updated alert rules and software associations.
request("POST", "/reports/generate", json={
    "report_type": "compliance",
    "scope": "cybersecurity_threat_alerts",
    "threats": threats,
    "associated_software_vulnerabilities": associated_vulnerabilities,
    "updated_alerts": alerts,
})
request("GET", "/compliance/reports")

