import requests

BASE_URL = "https://api.socbench.example"

template_response = requests.post(
    f"{BASE_URL}/billing/templates",
    json={
        "template_name": "Streamlined Utility Invoicing",
        "parameters": {
            "alert_usage_threshold": "unusual",
            "alert_monitoring": "enabled",
        },
    },
)
